/* Scoped compatibility fixes for markup generated by Dash 4.5.
 * DataTable exposes no per-row input/paginator ARIA props. Reconcile labels
 * after React replaces or reuses rows; never replace controls or their handlers.
 */
(function () {
  function setAttribute(element, name, value) {
    if (element.getAttribute(name) !== value) element.setAttribute(name, value);
  }

  function reconcile() {
    const table = document.getElementById("tabela-vagas");
    if (table) {
      const pagination = {
        "first-page": "Primeira página de anúncios",
        "previous-page": "Página anterior de anúncios",
        "next-page": "Próxima página de anúncios",
        "last-page": "Última página de anúncios",
      };
      for (const [className, label] of Object.entries(pagination)) {
        const button = table.querySelector(`button.${className}`);
        if (button) {
          setAttribute(button, "aria-label", label);
          setAttribute(button, "title", label);
        }
      }
      for (const input of table.querySelectorAll('.dash-select-cell input[type="radio"]')) {
        const row = input.closest("tr");
        const id = row.querySelector('td[data-dash-column="id_vaga"]');
        const title = row.querySelector('td[data-dash-column="title"]');
        if (id && title) setAttribute(input, "aria-label", `Selecionar anúncio ${id.textContent.trim()}: ${title.textContent.trim()}`);
      }
      const pageInput = table.querySelector(".current-page");
      if (pageInput) setAttribute(pageInput, "aria-label", "Página atual dos anúncios");
      for (const cell of table.querySelectorAll(".dash-filter[data-dash-column]")) {
        const header = table.querySelector(`th.dash-header[data-dash-column="${cell.dataset.dashColumn}"] .column-header-name`);
        const name = header ? header.textContent.trim() : cell.dataset.dashColumn;
        const input = cell.querySelector('input:not([type="button"])');
        if (input) setAttribute(input, "aria-label", `Filtrar coluna ${name}`);
        const toggle = cell.querySelector(".dash-filter--case");
        if (toggle) {
          setAttribute(toggle, "aria-label", `Distinguir maiúsculas e minúsculas na coluna ${name}`);
          setAttribute(toggle, "aria-pressed", String(toggle.classList.contains("dash-filter--case--sensitive")));
        }
      }
    }
    for (const [selector, label] of [
      ["#f-tam .dash-range-slider-min-input", "Tamanho mínimo da descrição em caracteres"],
      ["#f-tam .dash-range-slider-max-input", "Tamanho máximo da descrição em caracteres"],
    ]) {
      const input = document.querySelector(selector);
      if (input) setAttribute(input, "aria-label", label);
    }
    for (const proxy of document.querySelectorAll(".dash-dropdown-wrapper > .dash-dropdown-focus-target")) {
      const button = proxy.parentElement.querySelector("button.dash-dropdown");
      setAttribute(proxy, "tabindex", "-1");
      if (button) setAttribute(button, "tabindex", button.disabled ? "-1" : "0");
    }
  }

  let scheduled = false;
  const observer = new MutationObserver(function () {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(function () {
      scheduled = false;
      reconcile();
    });
  });
  function start() {
    reconcile();
    observer.observe(document.body, {
      subtree: true, childList: true, characterData: true,
      attributes: true, attributeFilter: ["tabindex", "class", "disabled"],
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start, {once: true});
  else start();
})();
